// Package diagdocs generates docs/errors from the code table and the
// reproducers, and docs/cue-errors.md from the menagerie. Tests keep the
// generated files in lockstep; nothing here is run by hand.
package diagdocs

import (
	"fmt"
	"strings"

	"golang.org/x/tools/txtar"

	"github.com/sdboyer/thema/diag"
)

const header = "<!-- Generated by go test ./diag; do not edit. -->\n\n"

// Page is what one code's page is generated from.
type Page struct {
	Info     diag.CodeInfo
	Prose    string
	Inputs   []txtar.File
	Rendered string
}

// ErrorPage renders docs/errors/<code>.md.
func ErrorPage(p Page) string {
	var b strings.Builder
	b.WriteString(header)
	fmt.Fprintf(&b, "# %s: %s\n\n", p.Info.Code, p.Info.Title)
	if p.Info.Retired != "" {
		fmt.Fprintf(&b, "**Retired.** %s\n", p.Info.Retired)
		return b.String()
	}
	if p.Prose != "" {
		b.WriteString(p.Prose)
		b.WriteString("\n\n")
	}
	if p.Info.Internal != "" {
		fmt.Fprintf(&b, "This condition cannot arise when thema's checker is sound: %s.\n\n", p.Info.Internal)
		b.WriteString("If thema reports it, the bug is in thema, not in the lineage or the data.\nPlease report it at https://github.com/sdboyer/thema/issues with the lineage\nand, for a translation, the instance.\n")
	}
	if len(p.Inputs) > 0 {
		b.WriteString("## Example\n\n")
		for _, f := range p.Inputs {
			fmt.Fprintf(&b, "`%s`:\n\n", f.Name)
			fmt.Fprintf(&b, "```%s\n%s```\n\n", lang(f.Name), string(f.Data))
		}
	}
	if p.Rendered != "" {
		b.WriteString("thema reports:\n\n")
		fmt.Fprintf(&b, "```\n%s```\n", p.Rendered)
	}
	return b.String()
}

// Index renders docs/errors/README.md.
func Index(pages []Page) string {
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("# Error codes\n\n")
	b.WriteString("Every diagnostic thema reports carries a code. A code's meaning never changes; a code that is no longer reported is retired, not reused. The codes are grouped by hundreds:\n\n")
	b.WriteString("| Range | Area |\n|---|---|\n")
	for _, g := range groups {
		fmt.Fprintf(&b, "| %s | %s |\n", g.rng, g.area)
	}
	b.WriteString("\n| Code | Severity | Title |\n|---|---|---|\n")
	for _, p := range pages {
		title := p.Info.Title
		if p.Info.Retired != "" {
			title = "retired: " + title
		}
		fmt.Fprintf(&b, "| [%s](%s.md) | %s | %s |\n", p.Info.Code, p.Info.Code, p.Info.Severity, title)
	}
	return b.String()
}

var groups = []struct{ rng, area string }{
	{"E01xx", "the shape of authoring files and of the lineage"},
	{"E02xx", "versions and compatibility"},
	{"E03xx", "lenses"},
	{"E04xx", "lacunas"},
	{"E05xx", "data validation"},
	{"E06xx", "loading, modules and the CLI's inputs"},
	{"E09xx", "thema itself: internal errors and CUE errors thema does not recognize"},
}

// MenagerieCase is one recorded error shape.
type MenagerieCase struct {
	Name    string
	Section string
	Files   []MenagerieFile
	Record  string
}

// MenagerieFile is one input of a menagerie case.
type MenagerieFile struct{ Name, Text string }

// CueErrors renders docs/cue-errors.md from the menagerie.
func CueErrors(cases []MenagerieCase) string {
	var b strings.Builder
	b.WriteString(header)
	b.WriteString(`# CUE error shapes

Every error the CUE evaluator produces that thema recognizes or depends on, with
a minimal input and everything ` + "`cue/errors`" + ` exposes about the result: the
error's text, each entry of ` + "`errors.Errors`" + ` with its message format and
argument types, its path, its position and input positions, and the
` + "`errors.Details`" + ` rendering. ` + "`diag/shapes.go`" + ` matches on these shapes; a CUE
upgrade that changes one fails the digest in ` + "`diag/menagerie_test.go`" + `.

What to expect of CUE's errors, as the catalogue shows:

- ` + "`Position()`" + ` is often invalid while ` + "`InputPositions()`" + ` carries the data.
  Conflicts between two concrete values are the usual case: both values are
  inputs, and neither is the position.
- ` + "`InputPositions()`" + ` may repeat a position.
- ` + "`Path()`" + ` is empty for syntax errors, import and load errors, and some
  reference errors.
- A failed disjunction unrolls into a positionless header, "K errors in empty
  disjunction", followed by one entry per arm.
- ` + "`error()`" + ` in CUE strips its own framing: the author's message is the whole
  text, and the position is the call site.
- ` + "`errors.Details`" + ` shows paths relative to its Cwd; ` + "`Position()`" + ` keeps the
  full filename.

`)
	section := ""
	for _, c := range cases {
		if c.Section != section {
			section = c.Section
			fmt.Fprintf(&b, "## %s\n\n", section)
		}
		fmt.Fprintf(&b, "### %s\n\n", c.Name)
		for _, f := range c.Files {
			fmt.Fprintf(&b, "`%s`:\n\n```%s\n%s\n```\n\n", f.Name, lang(f.Name), f.Text)
		}
		fmt.Fprintf(&b, "```\n%s```\n\n", c.Record)
	}
	return b.String()
}

func lang(name string) string {
	switch {
	case strings.HasSuffix(name, ".cue"), strings.HasSuffix(name, ".thema"):
		return "cue"
	case strings.HasSuffix(name, ".json"):
		return "json"
	case strings.HasSuffix(name, ".yaml"), strings.HasSuffix(name, ".yml"):
		return "yaml"
	}
	return ""
}
